mapper.sql:
SELECT 'WHAT_IF' AS history_type, s.simulation_id AS source_id, s.scenario_name, NULL AS analysis_type, s.created_at, s.expected_asset, s.monthly_spending_amount, s.monthly_saving_amount, s.monthly_investment_amount, NULL AS generation_source, NULL AS result_json, EXISTS ( SELECT 1 FROM strategy_application sa WHERE sa.user_id = s.user_id AND sa.simulation_id = s.simulation_id AND sa.application_id = ( SELECT active.application_id FROM strategy_application active WHERE active.user_id = s.user_id AND active.source_type = 'AI_RECOMMENDATION' AND active.analysis_id IS NOT NULL AND active.applied_monthly_spending_amount IS NOT NULL AND active.applied_monthly_saving_amount IS NOT NULL AND active.applied_monthly_investment_amount IS NOT NULL AND active.applied_expected_return_rate IS NOT NULL ORDER BY active.applied_at DESC, active.application_id DESC LIMIT 1 ) ) AS applied FROM simulation s WHERE s.user_id = #{userId} AND s.is_saved = TRUE
UNION ALL
SELECT 'AI' AS history_type, a.analysis_id AS source_id, NULL AS scenario_name, a.analysis_type, a.created_at, NULL AS expected_asset, NULL AS monthly_spending_amount, NULL AS monthly_saving_amount, NULL AS monthly_investment_amount, a.generation_source, a.result_json, EXISTS ( SELECT 1 FROM strategy_application sa WHERE sa.user_id = a.user_id AND sa.analysis_id = a.analysis_id AND sa.application_id = ( SELECT active.application_id FROM strategy_application active WHERE active.user_id = a.user_id AND active.source_type = 'AI_RECOMMENDATION' AND active.analysis_id IS NOT NULL AND active.applied_monthly_spending_amount IS NOT NULL AND active.applied_monthly_saving_amount IS NOT NULL AND active.applied_monthly_investment_amount IS NOT NULL AND active.applied_expected_return_rate IS NOT NULL ORDER BY active.applied_at DESC, active.application_id DESC LIMIT 1 ) ) AS applied FROM ai_analysis a WHERE a.user_id = #{userId}
